mapper.select:
SELECT
    t.*
from(
        SELECT
            clii.* ,
            ROW_NUMBER() OVER (PARTITION BY clii.INSURANCE_TYPE ORDER BY clii.INSURANCE_DATE_TO desc)  AS row_flag
        FROM CON_LEASE_ITEM_INSURANCE clii
        WHERE clii.CON_LEASE_ITEM_ID = #{contractLeaseItemId}
    ) t WHERE t.row_flag = 1
        AND t.INSURANCE_DATE_TO < TO_DATE(TO_CHAR(SYSDATE,'yyyy-MM-dd'),'yyyy-MM-dd')
